import { Compiler, DEFAULT_COMPILER_OPTIONS, type Diagnostic, type File, path, ts } from '@servicenow/sdk-build-core'
import { fail } from 'assert'
import { Project, type ProjectFile } from '../src'
import merge from 'lodash/merge'
import type { PartialDeep } from 'type-fest'
import * as fs from 'node:fs'
import { diffAsXml } from 'diff-js-xml'
import type memfs from 'memfs'

/**
 * Test context for a given project directory
 */
class TestContext {
    private sharedCompiler: Compiler | null = null

    constructor(private readonly options: { rootDir: string }) {}

    /**
     * Call in beforeAll() hook.
     */
    initialize(): void {
        this.sharedCompiler = new Compiler(fs, {
            rootDir: this.options.rootDir,
            compilerOptions: DEFAULT_COMPILER_OPTIONS,
            sourceFilePaths: [],
        })
    }

    /**
     * Call in afterEach() hook.
     */
    cleanup(): void {
        if (!this.sharedCompiler) {
            return
        }

        // Remove all test-added source files and reset compiler state
        const sourceFiles = this.sharedCompiler.getSourceFiles()
        for (const sourceFile of sourceFiles) {
            const filePath = sourceFile.getFilePath()
            if (!filePath.includes('$$GENERATED$$')) {
                this.sharedCompiler.removeSourceFile(sourceFile)
            }
        }
        this.sharedCompiler.addGlobalTableDefinitionFile()
        this.sharedCompiler.addAvailableModules()
        this.sharedCompiler.resetModuleProject()
    }

    createProject(projectOptions?: PartialDeep<ConstructorParameters<typeof Project>[0]>): Project {
        if (!this.sharedCompiler) {
            throw new Error(
                'TestContext not initialized. Call ctx.initialize() in beforeAll() hook before using createProject().'
            )
        }
        return createProject({
            ...projectOptions,
            compiler: this.sharedCompiler,
            rootDir: projectOptions?.rootDir ?? this.options.rootDir,
        })
    }

    getCompiler(): Compiler {
        if (!this.sharedCompiler) {
            throw new Error('TestContext not initialized. Call ctx.initialize() in beforeAll() hook.')
        }
        return this.sharedCompiler
    }
}

export function createTestContext(options: { rootDir: string }): TestContext {
    return new TestContext(options)
}

export function createProject(values?: PartialDeep<ConstructorParameters<typeof Project>[0]>) {
    return new Project(
        merge(
            {
                packageJson: { name: 'x_test', version: '1.0.0' },
                config: {
                    scope: 'x_test',
                    scopeId: Array(32).fill('1').join(''),
                },
            },
            values
        ) as any
    )
}

/** identity template string function to get XML syntax highlighting */
export const xml = (strings: TemplateStringsArray, ...values: any[]) => {
    return String.raw({ raw: strings }, ...values)
}

const sourceFileFromTextOrFunction = (project: Project, textOrFunc: string | (() => void)): ProjectFile => {
    return project.addFile({ path: 'generated.now.ts', content: textOrFunc.toString() })
}

export const runTestOnFunction = async (project: Project, textOrFunc: string | (() => void)) => {
    return sourceFileFromTextOrFunction(project, textOrFunc).getDiagnostics()
}

export const validateDiagnostic = (output: Diagnostic[], source: ts.SyntaxKind, message: string) => {
    const error = output.find((e) => e.code === source)
    if (!error) {
        const messages = output.map((d) => `  • [${ts.SyntaxKind[d.code]}]: ${d.message}`).join('\n')
        fail(`expected to find error for ${ts.SyntaxKind[source]}. Got:\n\n${messages || '  *no diagnostics*'}`)
    }
    expect(error.message).toBe(message)
}

/**
 * Compare two XML strings and return the differences.
 * @param xml1 source xml
 * @param xml2 xml to compare against
 * @returns array of differences if any found
 */
export const compareOutputXml = (xml1: string, xml2: string) => {
    const xmlIgnoredProperties = {
        sys_class_name: { skipKey: true },
        sys_update_name: { skipKey: true },
        sys_mod_count: { skipKey: true },
        sys_created_by: { skipKey: true },
        sys_created_on: { skipKey: true },
        sys_updated_by: { skipKey: true },
        sys_updated_on: { skipKey: true },
        sys_name: { skipKey: true },
        sys_package: { skipKey: true },
        sys_policy: { skipKey: true },
    }

    let differences: any[] = []

    diffAsXml(xml1, xml2, xmlIgnoredProperties, {}, (diffs: any[]) => {
        differences = diffs
    })

    return differences
}

/**
 * Helper to write a round-trip test Fluent->XML->Fluent.
 *
 * Usage:
 * 1) add all expected IDs with `addId` or `addCompositeId`
 * 2) add all fluent fragments via `addFluentFragment`
 * 3) call `verify`.
 *
 * The code will:
 * - generate the XML from the Fluent fragments
 * - ensure that one XML file is generated for each registered ID
 * - generate the Fluent files and ensure that there are no differences, as the XML and the Fluent files should match
 */
export class FluentXmlFluentTest {
    private readonly expectedXmlFileNames: string[] = []
    private readonly fluentFiles: File[] = []

    constructor(private readonly project: Project) {}

    addId(table: string, name: string): string {
        return this.project.registerExplicitId(table, name)
    }

    addCoalesceId(table: string, key: Record<string, string>): string {
        return this.project.registerCoalesceId(table, key)
    }

    addExpectedXmlFileNames(...names: string[]): void {
        this.expectedXmlFileNames.push(...names)
    }

    addFluentFragment(content: string) {
        this.fluentFiles.push({
            path: `fluent-${this.fluentFiles.length + 1}.now.ts`,
            content,
        })
    }

    async verify() {
        // Fluent -> XML
        const projectFiles = this.fluentFiles.map((file) => this.project.addFile(file))
        const originalContents = projectFiles.reduce(
            (map, file) => {
                map[file.getPath()] = file.getContent()
                return map
            },
            {} as Record<string, string>
        )

        const xmlOutputs: File[] = (await Promise.all(projectFiles.map((pf) => pf.getOutput()))).flat()
        const xmlOutputNames = xmlOutputs.map(FluentXmlFluentTest.fileNameOf)
        xmlOutputNames.sort()
        this.expectedXmlFileNames.sort()
        expect(xmlOutputNames).toStrictEqual(this.expectedXmlFileNames)

        // Round-trip: should have no changes since the XML match the original .now.ts files
        const {
            changedFiles: [changedFile],
        } = await this.project.transform(xmlOutputs)

        if (changedFile) {
            expect(changedFile.getContent()).toBe(originalContents[changedFile.getPath()] ?? '')
        }
    }

    private static fileNameOf(file: File): string {
        return file.path.split('/').pop()
    }
}

/**
 * Helper to write a round-trip test XML->Fluent->XML.
 *
 * The code will:
 * - generate all the Fluent files from the XML files
 * - ensure that the number of generated Fluent files is as expected
 * - regenerate the XML files from the Fluent files
 * - compare the original and generated files, ignoring various properties such as `sys_created_on`
 */
export class XmlFluentXmlTest {
    constructor(
        private readonly project: Project,
        private readonly originalDirectory: string,
        private readonly originalFiles: (string | File)[]
    ) {}

    async verify() {
        // XML -> Fluent
        const { changedFiles } = await this.project.transform(this.originalFiles)

        // Roundtrip Fluent -> XML
        const fluentFiles = changedFiles.map((file) => {
            return this.project.addFile({
                path: `${file.getPath().split('/').pop()}`,
                content: file.getContent(),
            })
        })

        const xmlOutputs = (await Promise.all(fluentFiles.map((file) => file.getOutput()))).flat()

        const originalContents = this.originalFiles.reduce(
            (map, file) => {
                if (typeof file === 'string') {
                    map[path.basename(file)] = fs.readFileSync(path.join(this.originalDirectory, file), 'utf-8')
                } else {
                    map[path.basename(file.path)] = file.content
                }

                return map
            },
            {} as Record<string, string>
        )

        for (const output of xmlOutputs) {
            const fileName = path.basename(output.path)
            const originalContent = originalContents[fileName]
            if (originalContent) {
                const fileDifferences = compareOutputXml(originalContent, output.content)

                if (fileDifferences.length) {
                    console.table(fileDifferences)
                    fail(`Unexpected changes found in XML file: ${fileName}`)
                }
            } else {
                fail(`Unexpected XML file found: ${fileName}`)
            }
        }

        for (const fileName of Object.keys(originalContents)) {
            if (!xmlOutputs.some((file) => path.basename(file.path) === fileName)) {
                fail(`Expected XML file was not found: ${fileName}`)
            }
        }
    }
}

export function readFile(filePath: string) {
    return fs.readFileSync(filePath).toString('utf-8')
}

export function loadNodeModules(directories: { from: string; to: string }[], vol: memfs.Volume) {
    function copyRecursive(srcDir: string, destDir: string) {
        if (destDir.endsWith('/node_modules')) {
            return
        }

        if (!fs.existsSync(srcDir)) {
            return
        }
        if (!vol.existsSync(destDir)) {
            vol.mkdirSync(destDir, { recursive: true })
        }

        for (const entry of fs.readdirSync(srcDir)) {
            const srcPath = path.join(srcDir, entry)
            const destPath = path.join(destDir, entry)
            const stat = fs.statSync(srcPath)
            if (stat.isDirectory()) {
                copyRecursive(srcPath, destPath)
            } else if (stat.isFile()) {
                const data = fs.readFileSync(srcPath)
                vol.writeFileSync(destPath, data)
            }
        }
    }

    directories.forEach((directory) => {
        const srcDir = path.join(__dirname, directory.from)
        copyRecursive(srcDir, directory.to)
    })
}

export function copyProjectToVolume(directories: { from: string; to: string }, vol: memfs.Volume) {
    loadNodeModules(
        [
            { from: '../../../sdk', to: '/node_modules/@servicenow/sdk' },
            { from: '../../../core', to: '/node_modules/@servicenow/sdk-core' },
            { from: '../../../api', to: '/node_modules/@servicenow/sdk-api' },
        ],
        vol
    )
    copyProjectFilesRecursive(directories, vol)
    return vol
}

function copyProjectFilesRecursive(directories: { from: string; to: string }, vol: memfs.Volume) {
    if (!vol.existsSync(directories.to)) {
        vol.mkdirSync(directories.to)
    }

    for (const entry of fs.readdirSync(directories.from)) {
        const srcDir = path.join(directories.from, entry)
        const destDir = path.join(directories.to, entry)
        const stat = fs.statSync(srcDir)
        if (!stat) {
            continue
        }
        if (stat.isDirectory()) {
            copyProjectFilesRecursive({ from: srcDir, to: destDir }, vol)
        } else if (stat.isFile()) {
            const data = fs.readFileSync(srcDir, 'utf-8')
            vol.writeFileSync(destDir, data)
        }
    }
    return vol
}

export function getUtcTime(localHours: number, localMinutes: number, localSeconds: number): string {
    // Create a date with the local time components
    const localDate = new Date(1970, 0, 1, localHours, localMinutes, localSeconds)
    // Get UTC components
    const utcHours = localDate.getUTCHours()
    const utcMinutes = localDate.getUTCMinutes()
    const utcSeconds = localDate.getUTCSeconds()

    // Format expected time string
    const utcYear = localDate.getUTCFullYear()
    const utcMonth = String(localDate.getUTCMonth() + 1).padStart(2, '0')
    const utcDay = String(localDate.getUTCDate()).padStart(2, '0')

    return `${utcYear}-${utcMonth}-${utcDay} ${String(utcHours).padStart(2, '0')}:${String(utcMinutes).padStart(2, '0')}:${String(utcSeconds).padStart(2, '0')}`
}

export function getTimeComponents(utcDateString: string): { hours: number; minutes: number; seconds: number } {
    // Should preserve helper function format and update values
    // Convert UTC time from XML (22:30:00) to local time components
    const utcDate = new Date(utcDateString)
    return {
        hours: utcDate.getHours(),
        minutes: utcDate.getMinutes(),
        seconds: utcDate.getSeconds(),
    }
}
